 /* ---------------------------------------------------------------- */
 /* Motion                                                           */
 /* ---------------------------------------------------------------- */

 @keyframes hero-in {
   from {
     opacity: 0;
     transform: translateY(10px);
     filter: blur(4px);
   }
   to {
     opacity: 1;
     transform: none;
     filter: blur(0);
   }
 }

 @keyframes reveal-up {
   from {
     opacity: 0;
     transform: translateY(24px);
   }
   to {
     opacity: 1;
     transform: none;
   }
