     transition-duration: 0.001ms !important;
     scroll-behavior: auto !important;
   }

   .js-reveal [data-reveal] {
     opacity: 1;
     transform: none;
   }
 }

 /* ---------------------------------------------------------------- */
 /* Responsive                                                       */
 /* ---------------------------------------------------------------- */

 @media (max-width: 860px) {
   .site-nav {
     display: none;
   }
 }

 @media (max-width: 640px) {
   .compare {
     grid-template-columns: 1fr;
   }

   .gap__row {
     grid-template-columns: 78px 1fr 34px;
     gap: 10px;
   }
 }

