   flex-wrap: wrap;
   align-items: center;
   gap: 10px 16px;
 }

 .demo__label {
   display: inline-flex;
   align-items: center;
   padding: 4px 12px;
   border: 1px solid color-mix(in srgb, var(--amber) 32%, transparent);
