 .demo__health {
   display: inline-flex;
   align-items: center;
   gap: 7px;
   padding: 4px 11px;
   border: 1px solid var(--line);
   border-radius: var(--r-pill);
   color: var(--faint);
   font-size: 0.6875rem;
 }

 .demo__dot {
   width: 6px;
   height: 6px;
   border-radius: 50%;
   background: var(--green);
   box-shadow: 0 0 0 3px color-mix(in srgb, var(--green) 14%, transparent);
 }

 .demo__transcript,
 .demo__live {
   padding: 22px;
 }

 .demo__thread {
   min-height: 280px;
 }

 .demo__exchange + .demo__exchange {
   margin-top: 22px;
 }

 .demo__msg {
   display: flex;
   gap: 12px;
 }

 .demo__msg + .demo__msg {
   margin-top: 18px;
 }

 .demo__msg--user {
   justify-content: flex-end;
 }

 .demo__msg--assistant {
   align-items: flex-start;
