     opacity 0.5s var(--ease-apple-out),
     transform 0.5s var(--ease-apple-out);
 }

 .demo__msg--assistant.is-pending {
   opacity: 0;
   transform: translateY(8px);
 }

 .demo__bubble {
   max-width: 78%;
   padding: 10px 14px;
   border: 1px solid var(--line);
   border-radius: 18px 18px 6px 18px;
   background: var(--surface-hover);
   font-size: 0.9375rem;
   line-height: 1.55;
   white-space: pre-wrap;
   overflow-wrap: anywhere;
 }

 .demo__msg-body {
   flex: 1;
   min-width: 0;
   display: flex;
   flex-direction: column;
   gap: 14px;
 }

 .demo__reply {
   color: var(--muted);
   font-size: 0.9375rem;
   line-height: 1.6;
 }

 .demo__avatar {
   display: grid;
   place-items: center;
   width: 26px;
   height: 26px;
   flex: none;
   margin-top: 2px;
