   background: linear-gradient(140deg, var(--accent-strong), var(--accent));
   color: var(--bg);
 }

 .demo__typing {
   display: flex;
   align-items: center;
   gap: 9px;
   margin-top: 18px;
 }

 .typing__dots {
   display: inline-flex;
   gap: 3px;
 }

 .typing__dots i {
   width: 5px;
   height: 5px;
   border-radius: 50%;
   background: var(--faint);
   animation: caret-blink 1.2s infinite ease-in-out;
 }

 .typing__dots i:nth-child(2) { animation-delay: 0.15s; }
 .typing__dots i:nth-child(3) { animation-delay: 0.3s; }

 .demo__composer {
   display: flex;
   align-items: flex-end;
   gap: 10px;
   margin-top: 18px;
   padding: 8px 9px 8px 16px;
   border: 1px solid var(--line);
   border-radius: 22px;
   background: var(--surface);
   transition: border-color 0.16s var(--ease-tactile);
 }

 .demo__composer:focus-within {
   border-color: color-mix(in srgb, var(--accent) 42%, transparent);
 }

 .demo__input {
   flex: 1;
   min-width: 0;
   max-height: 140px;
   padding: 8px 0;
   border: 0;
   background: transparent;
   color: var(--text);
   font-size: 0.9375rem;
   line-height: 1.5;
   resize: none;
   outline: none;
 }

 .demo__input::placeholder {
   color: var(--faint);
 }

 .demo__send {
   display: grid;
   place-items: center;
   width: 34px;
   height: 34px;
   flex: none;
   border-radius: 50%;
   background: var(--text);
   color: var(--bg);
   transition:
     transform 0.15s var(--ease-tactile),
     opacity 0.15s var(--ease-tactile);
 }

 .demo__send:hover {
   transform: translateY(-1px);
 }

 .demo__chips {
   display: flex;
   flex-wrap: wrap;
   gap: 7px;
   margin-top: 14px;
 }

 .demo__chip {
   display: inline-flex;
   align-items: center;
   padding: 6px 12px;
   border: 1px solid var(--line);
   border-radius: var(--r-pill);
   background: var(--surface);
   color: var(--muted);
   font-size: 0.8125rem;
   text-align: left;
   transition:
     background-color 0.15s var(--ease-tactile),
     border-color 0.15s var(--ease-tactile),
     color 0.15s var(--ease-tactile),
     transform 0.15s var(--ease-tactile);
 }

 .demo__chip:hover {
   transform: translateY(-1px);
   border-color: var(--line-strong);
   background: var(--surface-hover);
   color: var(--text);
 }

 /* ---------------------------------------------------------------- */
 /* Run it                                                           */
 /* ---------------------------------------------------------------- */

 .run {
   display: flex;
   flex-direction: column;
   gap: 32px;
 }

 .run__grid {
   display: grid;
   gap: 28px;
   grid-template-columns: minmax(0, 1fr);
 }

 @media (min-width: 960px) {
   .run__grid {
     grid-template-columns: minmax(0, 0.85fr) minmax(0, 1.15fr);
