 }

 .copy-btn--inline {
   position: static;
   flex: none;
   padding: 3px 9px;
   font-size: 0.6875rem;
   opacity: 1;
 }

 .section__more {
   margin-top: 32px;
 }

 .status-note--muted {
   margin-top: 10px;
   font-weight: 400;
   color: var(--muted);
 }

